    triggerLogs = mysqlTable("trigger_logs", {
      id: int("id").autoincrement().primaryKey(),
      userId: int("userId"),
      // nullable — email-only (Stripe) students have no userId
      studentEmail: varchar("studentEmail", { length: 320 }),
      // set when userId is null
      triggerType: varchar("triggerType", { length: 32 }).notNull(),
      // 'struggling' | 'plateau' | 'inactive' | 'exam_approaching' | 'milestone'
      emailSubject: varchar("emailSubject", { length: 256 }).notNull(),
      emailBodyPreview: text("emailBodyPreview"),
      // first 200 chars of the email body for admin review
      sentAt: timestamp("sentAt").defaultNow().notNull(),
      cooldownUntil: timestamp("cooldownUntil").notNull(),
      // don't send same trigger type again until this date
      /** Issue R: written BEFORE sendMail so cooldown is claimed even on SMTP failure.
       *  'pending' → row reserved, send in progress
       *  'sent'    → sendMail succeeded
       *  'failed'  → sendMail threw; cooldown still applies to prevent duplicate sends */
      status: varchar("status", { length: 16 }).notNull().default("sent")
    }, (t2) => [
      // Issue O: composite index for the two cooldown queries (userId + sentAt, userId + triggerType + sentAt)
      index("trigger_logs_userid_sentat_idx").on(t2.userId, t2.sentAt),
      index("trigger_logs_email_sentat_idx").on(t2.studentEmail, t2.sentAt)
    ]);
