async function hasTrainingRecord(emailInput) {
  const db = await getDb();
  if (!db) return false;
  const email = normalizeEmail(emailInput);
  const [session] = await db.select({ id: learningActivitySessions.id }).from(learningActivitySessions).where(and34(eq38(learningActivitySessions.studentEmail, email), gt9(learningActivitySessions.activeSeconds, 0))).limit(1);
  if (session) return true;
  const [attestation] = await db.select({ id: trainingAttestations.id }).from(trainingAttestations).where(eq38(trainingAttestations.operatorEmail, email)).limit(1);
  return !!attestation;
}

