// shared/ceuLearning.ts
function moduleMinimumMinutes(module) {
  return module.activities.reduce((sum, a) => sum + a.minutes, 0);
}
function isCeuModuleComplete(record, moduleId) {
  const module = record.modules[moduleId];
  return Boolean(
    module?.completedAt || module?.exerciseAttempts.some((attempt) => attempt.passed)
  );
}
function ceuReadiness(course, record) {
  const checksPassed = course.modules.every(
    (m) => m.checks.every((q) => record.modules[m.id]?.checks[q.id]?.correct)
  );
  const exercisesPassed = course.modules.every(
    (m) => record.modules[m.id]?.exerciseAttempts.some((a) => a.passed)
  );
  const modulesCompleted = course.modules.every(
    (module) => isCeuModuleComplete(record, module.id)
  );
  const moduleTimeMet = course.modules.every(
    (m) => (record.modules[m.id]?.activeSeconds ?? 0) >= moduleMinimumMinutes(m) * 60
  );
  const recordedSeconds = course.modules.reduce(
    (sum, m) => sum + (record.modules[m.id]?.activeSeconds ?? 0),
    0
  );
  const timeMet = moduleTimeMet && recordedSeconds >= course.plannedMinutes * 60;
  const assessmentPassed = record.attempts.some((a) => a.passed);
  return {
    checksPassed,
    exercisesPassed,
    modulesCompleted,
    moduleTimeMet,
    recordedSeconds,
    timeMet,
    assessmentPassed,
    ready: modulesCompleted && assessmentPassed
  };
}

