// server/ceu/assessment.ts
var legacy = legacyAssessments_default;
function shuffle2(values) {
  const result = [...values];
  for (let i = result.length - 1; i > 0; i--) {
    const j = randomInt2(i + 1);
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}
function issueCeuExam(course) {
  const pool = [...course.finalAssessment, ...course.alternateFinalAssessment ?? []];
  return shuffle2(course.modules.flatMap((module) => {
    const count10 = course.finalAssessment.filter((q) => q.objective === module.id).length;
    return shuffle2(pool.filter((q) => q.objective === module.id)).slice(0, count10);
  })).map((q) => ({ questionId: q.id, choiceOrder: shuffle2(q.choices.map((_, i) => i)) }));
}
function ceuExamQuestions(course, manifest) {
  const archived = legacy[course.key];
  if (!manifest) return archived?.primary ?? course.finalAssessment;
  const pool = [
    ...course.finalAssessment,
    ...course.alternateFinalAssessment ?? [],
    ...archived?.primary ?? [],
    ...archived?.alternate ?? []
  ];
  return manifest.map((item) => {
    const q = pool.find((question) => question.id === item.questionId);
    if (!q || item.choiceOrder.length !== q.choices.length || new Set(item.choiceOrder).size !== q.choices.length || item.choiceOrder.some((i) => !Number.isInteger(i) || i < 0 || i >= q.choices.length))
      throw new Error("This assessment version is unavailable. Your saved answers have been preserved.");
    return { ...q, choices: item.choiceOrder.map((i) => q.choices[i]), correctIndex: item.choiceOrder.indexOf(q.correctIndex) };
  });
}
function ceuSampleQuestions(course) {
  return course.modules.map((module) => {
    const { correctIndex, explanation: explanation2, ...question } = module.checks[0];
    return question;
  });
}

