  const subheading = inPreview ? "Built from the questions you have answered so far." : "Built from the questions you just answered.";
  const topicsLine = weakTopics.length ? weakTopics.map(escapeHtml2).join(", ") : inPreview ? "None so far. You have answered every question correctly." : "None. You answered every preview question correctly.";
