      const issuedQuestions = issuedMockQuestions(manifest);
      const questionNums = input.answers.map((a) => a.questionNum);
      if (new Set(questionNums).size !== questionNums.length) {
        throw new TRPCError40({ code: "BAD_REQUEST", message: "Each exam question must appear exactly once." });
      }
      const availableRows = input.bankKey === "electrician-309a" ? await db.select({
        questionNum: certificationQuestions.bankItemNumber,
        correctIndex: certificationQuestions.correctIndex,
        module: certificationQuestions.module,
        topic: certificationQuestions.topic,
        difficulty: certificationQuestions.difficulty,
        explanation: certificationQuestions.explanation
      }).from(certificationQuestions).innerJoin(certificationBankVersions, eq55(certificationQuestions.bankVersionId, certificationBankVersions.id)).where(and46(
        eq55(certificationBankVersions.programKey, ELECTRICIAN_309A_PROGRAM_KEY),
        eq55(certificationBankVersions.bankKey, input.bankKey),
        eq55(certificationBankVersions.releaseChannel, "beta"),
        eq55(certificationBankVersions.active, true),
        inArray17(certificationQuestions.bankItemNumber, questionNums),
        eq55(certificationQuestions.contentStatus, "beta_approved"),
        eq55(certificationQuestions.publicEligibility, true)
      )) : await db.select({
        questionNum: questions.questionNum,
        correctIndex: questions.correctIndex,
        module: questions.module,
        topic: questions.topic,
        difficulty: questions.difficulty,
        explanation: questions.explanation
      }).from(questions).where(and46(
        eq55(questions.bankKey, manifest.bankKey),
        inArray17(questions.questionNum, questionNums),
        learnerVisibleQuestionFilter()
      ));
      const availableQuestionNums = new Set(availableRows.map((q) => q.questionNum));
      const questionMap = new Map((issuedQuestions ?? availableRows).map((q) => [q.questionNum, q]));
      const review2 = input.answers.map((answer) => {
        const q = availableQuestionNums.has(answer.questionNum) ? questionMap.get(answer.questionNum) : void 0;
        return {
          questionNum: answer.questionNum,
          scored: scoredIds.has(answer.questionNum),
          correctIndex: q?.correctIndex ?? null,
          explanation: q?.explanation ?? null
        };
      });
      const existingResponse = (saved) => ({
        success: true,
        persisted: true,
        score: saved.score,
        total: saved.total,
        pct: Math.round(saved.score / saved.total * 100),
        passed: saved.passed === "yes",
        unavailableCount: JSON.parse(saved.moduleBreakdown ?? "{}")[UNAVAILABLE_MOCK_MODULE]?.total ?? 0,
        moduleBreakdown: JSON.parse(saved.moduleBreakdown ?? "{}"),
        review: review2,
        reviewToken: manifest.version === 3 ? issueMockReviewToken(manifest) : void 0
      });
      if (existing) return existingResponse(existing);
      if (![...scoredIds].some((id3) => availableQuestionNums.has(id3))) {
        throw new TRPCError40({ code: "BAD_REQUEST", message: "None of this exam's questions are available for scoring. No result was saved. Your answers remain in this tab for review; please contact support." });
      }
