function classifyAppRoute(url) {
  const raw = url.split(/[?#]/, 1)[0];
  const path5 = raw !== "/" ? raw.replace(/\/$/, "") : raw;
  if (privatePaths.has(path5) || /^\/(?:activate\/[^/]+|training-hours\/records\/[^/]+)$/.test(path5)) return { kind: "private", path: path5 };
  if (publicPaths.has(path5) || cataloguePaths.has(path5) || /^\/blog\/[a-z0-9-]{1,200}$/.test(path5)) return { kind: "public", path: path5 };
  const paTool = /^\/us\/(?:practice|mock|flashcards)\/([a-z0-9-]+)$/.exec(path5);
  if (paTool && statePracticeBank(paTool[1]) && getCourseByKey(paTool[1])?.isActive) return { kind: "public", path: path5 };
  const activityCourse = /^\/courses\/([a-z0-9-]+)\/interactive$/.exec(path5);
  if (activityCourse && getCourseByKey(activityCourse[1])?.isActive) return { kind: "public", path: path5 };
  return { kind: "not-found", path: path5 };
}

// server/staticHead.ts
function escapeHtml3(value) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
function replaceStaticHead(template, head, title) {
  return template.replace(/<title>[^<]*<\/title>/g, () => `<title>${escapeHtml3(title)}</title>`).replace(/<meta (?:name="(?:description|robots|twitter:[^"]+)"|property="og:[^"]+")[^>]*>/g, "").replace(/<link rel="canonical"[^>]*>/g, "").replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>/g, "").replace("</head>", () => `${head}
</head>`);
}
function brandedShell(body) {
  return `<div data-ssr-fallback="true" id="ssr-page-shell">
    <header class="ssr-brand"><a href="/">Echelon Institute</a><span>AI-powered exam prep for skilled trades \u2014 water &amp; wastewater first</span></header>
    <div class="ssr-content">${body}</div>
    <nav class="ssr-nav" aria-label="Site navigation"><a href="/oit">Ontario OIT</a><a href="/canada/ontario">Ontario courses</a><a href="/wpi">WPI-aligned courses</a><a href="/electrician-309a">Free Ontario 309A prep</a><a href="/pricing">Pricing</a><a href="/blog">Blog</a><a href="/account">Sign in</a></nav>
  </div>`;
}
function prepareAppFallback(template, url) {
  const route = classifyAppRoute(url);
  const missing = route.kind === "not-found";
  const privatePage = route.kind === "private";
  const activityPage = route.kind === "public" && /^\/courses\/[a-z0-9-]+\/interactive$/.test(route.path);
  const title = missing ? "Page Not Found | Echelon Institute" : "Skilled Trades Study Resources | Echelon Institute";
  const description = missing ? "The requested page does not exist. Browse Echelon courses and study resources." : "AI-powered exam prep for the skilled-trades workforce, starting with water and wastewater. Canadian courses and supported US preparation, plus free Ontario 309A practice and mock exams.";
  const canonical2 = !missing && !privatePage && !activityPage ? `https://echeloninstitute.ca${route.path}` : null;
  const head = `<meta name="description" content="${escapeHtml3(description)}" />
    <meta name="robots" content="${missing || privatePage || activityPage ? "noindex, nofollow" : "index, follow"}" />
    <meta property="og:title" content="${escapeHtml3(title)}" />
    <meta property="og:description" content="${escapeHtml3(description)}" />
    ${canonical2 ? `<link rel="canonical" href="${escapeHtml3(canonical2)}" /><meta property="og:url" content="${escapeHtml3(canonical2)}" />` : ""}`;
  const body = missing ? brandedShell(`<h1>Page Not Found</h1><p>The page you are looking for does not exist.</p><p><a href="/">Return home</a> or choose a course below.</p>`) : `<div class="app-loading" role="status" aria-label="Loading page"><span class="app-loading-spinner" aria-hidden="true"></span></div><noscript><p>JavaScript is needed to open the study tools. <a href="/">Return home</a>.</p></noscript>`;
  const html = replaceAppRoot(replaceStaticHead(template, head, title), body);
  return { html, status: missing ? 404 : 200 };
}

// server/_core/vite.ts
async function createViteRenderer(server) {
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true
  };
  const config = typeof vite_config_default === "function" ? await vite_config_default({ command: "serve", mode: "development", isSsrBuild: false, isPreview: false }) : vite_config_default;
  const vite = await createViteServer({
    ...config,
    configFile: false,
    server: serverOptions,
    appType: "custom"
  });
  return vite;
}
function registerViteFallback(app, vite) {
  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;
    try {
      const clientTemplate = path2.resolve(
        import.meta.dirname,
        "../..",
        "client",
        "index.html"
      );
      let template = await fs2.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid()}"`
      );
      const fallback = prepareAppFallback(template, url);
      const page = await vite.transformIndexHtml(url, fallback.html);
      res.set("Cache-Control", "no-store");
      res.status(fallback.status).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e);
      next(e);
    }
  });
}
function serveStatic(app) {
  const distPath = process.env.NODE_ENV === "development" ? path2.resolve(import.meta.dirname, "../..", "dist", "public") : path2.resolve(import.meta.dirname, "public");
  if (!fs2.existsSync(distPath)) {
    console.error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`
    );
  }
  app.use(
    express.static(distPath, {
      index: false,
      redirect: false,
      setHeaders(res, filePath) {
        if (filePath.endsWith(".html")) {
          res.setHeader("Cache-Control", "no-cache, must-revalidate");
        }
      }
    })
  );
  app.use("/assets", (_req, res) => {
    res.status(404).set("Cache-Control", "no-store").end();
  });
  app.use("*", (req, res, next) => {
    try {
      const template = fs2.readFileSync(path2.resolve(distPath, "index.html"), "utf8");
      const fallback = prepareAppFallback(template, req.originalUrl);
      res.status(fallback.status).set({ "Cache-Control": "no-store", "Content-Type": "text/html; charset=utf-8" }).end(fallback.html);
    } catch (error) {
      next(error);
    }
  });
}

