import { desc as desc22, eq as eq56 } from "drizzle-orm";
var PUBLIC_BLOG_INDEX_LIMIT = 100;
var PUBLIC_BLOG_INDEX_DEADLINE_MS = 1200;
async function loadPublicBlogLinks() {
  const db = await getDb();
  if (!db) throw new Error("Public blog index unavailable");
  const posts = await db.select({ slug: blogPosts.slug, title: blogPosts.title, excerpt: blogPosts.excerpt }).from(blogPosts).where(eq56(blogPosts.published, 1)).orderBy(desc22(blogPosts.publishedAt), desc22(blogPosts.id)).limit(PUBLIC_BLOG_INDEX_LIMIT);
  return posts.map(repairPublishedArticle);
}
async function boundedPublicBlogLinks(load = loadPublicBlogLinks) {
  let timer;
  try {
    return await Promise.race([
      load(),
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error("Public blog index deadline exceeded")), PUBLIC_BLOG_INDEX_DEADLINE_MS);
      })
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}
function renderPublicBlogLinks(posts) {
  const links = posts.slice(0, PUBLIC_BLOG_INDEX_LIMIT).filter((post) => /^[a-z0-9-]{1,200}$/.test(post.slug)).map((post) => `<li><a href="/blog/${escapeHtml3(post.slug)}">${escapeHtml3(post.title)}</a><p>${escapeHtml3(post.excerpt)}</p></li>`).join("");
  return `<h2>Published Articles</h2>${links ? `<ul>${links}</ul>` : "<p>No published articles are available yet.</p>"}`;
}

