function buildUSStatePageMeta(state) {
  const body = US_STREAMS.map((stream) => {
    const program = state.programs.find((item) => item.stream === stream.key);
    const coverage = getUSProgramCoverage(program);
    const courses = matchedUSCourses(state, stream.key).filter((course) => course.courseKey !== "us-texas-class-d-water");
    const choices2 = courses.length ? `<ul>${courses.map((course) => `<li>${escapeHtml5(course.displayName)}: <a href="${escapeHtml5(usCourseHref(course, "practice", state.code))}">Practice</a> | <a href="${escapeHtml5(usCourseHref(course, "mock", state.code))}">Mock exam</a> | <a href="${escapeHtml5(usCourseHref(course, "flashcards", state.code))}">Flashcards</a></li>`).join("")}</ul>` : `<p>No state-matched course is linked for this stream yet.</p>`;
    return `<section><h2>${escapeHtml5(stream.label)}</h2><p>${escapeHtml5(usProgramLabel(program))}</p>
      <p><strong>Program authority:</strong> ${escapeHtml5(program.authorityName || "Not confirmed")}</p>
      <p><strong>Local levels:</strong> ${escapeHtml5(program.localLevels)}</p><p>${escapeHtml5(program.note)}</p>
      <p><strong>${escapeHtml5(coverage.label)}.</strong> ${escapeHtml5(coverage.note)}</p>
      ${program.authorityUrl ? `<p><a href="${escapeHtml5(program.authorityUrl)}">Official program information</a></p>` : ""}
      ${choices2}${program.sources.length ? `<h3>Sources and exam scope</h3><ul>${program.sources.map((source) => `<li><a href="${escapeHtml5(source.url)}">${escapeHtml5(source.title)}</a><p>${escapeHtml5(source.evidence)}</p></li>`).join("")}</ul>` : ""}</section>`;
  }).join("");
  const texasClassD = state.code === "TX" ? `<section><h2>Texas Class D Water</h2><p>Covers Texas water treatment and water distribution in one combined state-specific course.</p><p><a href="${SITE_URL3}/us-texas-class-d-water?country=US&amp;state=TX">Practice</a> | <a href="${SITE_URL3}/us-texas-class-d-water-mock?country=US&amp;state=TX">Mock exam</a> | <a href="${SITE_URL3}/us-texas-class-d-water-flashcards?country=US&amp;state=TX">Flashcards</a></p></section>` : "";
  const dedicatedCourseNeeds = state.code === "TX" ? state.dedicatedCourseNeeds.filter((note) => !note.includes("Texas Class D Water")) : state.dedicatedCourseNeeds;
  return {
    path: `/us/states/${state.slug}`,
    title: `${state.name} Operator Exam Routes | Echelon Institute`,
    description: `Check ${state.name} water and wastewater exam programs, official sources and confirmed shared WPI course matches. State-specific courses are listed separately.`,
    h1: `${state.name} operator exam preparation`,
    changefreq: "monthly",
    priority: "0.6",
    bodyHtml: `<p>Source check: ${US_RESEARCH_CHECKED_DATE}. Courses are linked only where the standardized exam and class match are confirmed. Local grades may not equal WPI class numbers. Your authority's current documents control.</p>${body}${texasClassD}
      ${dedicatedCourseNeeds.length ? `<h2>State-specific exam research</h2><p>The streams below use a state-specific exam. Echelon does not offer a course for them yet.</p><ul>${dedicatedCourseNeeds.map((note) => `<li>${escapeHtml5(note)}</li>`).join("")}</ul>` : ""}
      ${state.limits.length ? `<h2>What still needs confirmation</h2><ul>${state.limits.map((note) => `<li>${escapeHtml5(note)}</li>`).join("")}</ul>` : ""}
      <p><a href="/us/courses?state=${state.code}">View confirmed courses</a> or <a href="/us/states">view all states</a>.</p>`
  };
}
