async function ingestMunicipal(upsertJob, options2 = {}) {
  const errors = [];
  const sourceOutcomes = [];
  let totalFetched = 0;
  let successfulSources = 0;
  let failedSources = 0;
  const scrapeResults = await Promise.all(
    SCRAPERS.map(async (scraper) => {
      try {
        return { scraper, jobs: await scraper.fn(options2), error: null };
      } catch (error) {
        return { scraper, jobs: [], error };
      }
    })
  );
  for (const { scraper, jobs, error } of scrapeResults) {
    if (error) {
      failedSources++;
      sourceOutcomes.push({ source: scraper.sourceName, status: "failed", count: 0 });
      errors.push(`Scrape failed (${scraper.name}): ${error.message}`);
      console.log(`  \u2717 ${scraper.name}: ${error.message}`);
      continue;
    }
    try {
      let scraperCount = 0;
      for (const job of jobs) {
        try {
          await upsertJob({
            title: job.title,
            company: job.company,
            location: job.location,
            province: job.province ?? "ON",
            salary: null,
            jobType: "full-time",
            sourceUrl: job.sourceUrl,
            sourceName: scraper.sourceName,
            sourceType: "scraper",
            description: null,
            postedAt: job.postedAt ?? null
          });
          scraperCount++;
          totalFetched++;
        } catch (upsertErr) {
          errors.push(`Upsert error (${scraper.name}): ${upsertErr.message}`);
        }
      }
      if (scraperCount > 0) {
        console.log(
          `  \u2713 ${scraper.name}: ${scraperCount} water/wastewater jobs`
        );
      } else {
        console.log(`  \xB7 ${scraper.name}: 0 water/wastewater jobs found`);
      }
      successfulSources++;
      sourceOutcomes.push({ source: scraper.sourceName, status: "success", count: scraperCount });
    } catch (err) {
      failedSources++;
      sourceOutcomes.push({ source: scraper.sourceName, status: "failed", count: 0 });
      errors.push(`Scrape processing failed (${scraper.name}): ${err.message}`);
      console.log(`  \u2717 ${scraper.name}: processing failed: ${err.message}`);
    }
  }
  console.log(`  Total fetched from municipal scrapers: ${totalFetched}`);
  return { errors, totalFetched, successfulSources, failedSources, sourceOutcomes };
}

