// server/_core/interactiveContentCache.ts
var interactiveContentNoStore = (req, res, next) => {
  const segment = req.path.slice(req.path.lastIndexOf("/") + 1);
  const escaped = segment.replace(/\+/g, "%2B").replace(/&/g, "%26");
  const decoded = new URLSearchParams(`path=${escaped}`).get("path") ?? "";
  if (decoded.split(",").some((path5) => path5 === "interactive.getContent" || path5 === "interactive.getCatalog" || path5 === "interactive.startSession" || path5 === "quiz.getInteractiveQuestions")) {
    res.setHeader("Cache-Control", "private, no-store");
  }
  next();
};

